#include <lightnerx/network/message_batch.hpp>
#include <lightnerx/network/target.hpp>

lightnerx::compact::expected<void, std::error_code> broadcastEvent(
    const lightnerx::network::ConnectionManager& connections,
    std::vector<HSteamNetConnection> exceptions = {}
) {
    const std::array payload{std::byte{0x01}};
    const auto totalSize = sizeof(lightnerx::communication::Event) + payload.size();
    const lightnerx::communication::Event event{
        static_cast<std::uint16_t>(totalSize << 1),
        47
    };

    auto outbound = lightnerx::communication::event2OutboundMessage(
        event,
        payload,
        lightnerx::network::Target::broadcast(std::move(exceptions))
    );

    const auto queued = lightnerx::network::queueMessage(std::move(outbound));

    if (!queued) {
        return queued;
    }
    return lightnerx::network::flushAll(connections);
} Call broadcastEvent(connections) for everyone or broadcastEvent(connections, {connectionToSkip}) to exclude a handle, checking the returned lightnerx::compact::expected . What each step does ¶ queueMessage receives the OutboundMessage from the converter and stores the same message with its destination, without allocating another message or copying the bytes. The call consumes the message: on success, the batcher keeps it until the flush; if the queue is full, it releases it immediately. The caller must not call Release() or reuse the message after passing it to the queue. A null pointer is rejected with invalid_argument . flushAll iterates over pending messages, routes each one according to its destination, and releases the message received from the converter with Release() . All entries are processed and the queue is emptied even when send errors occur. The return value indicates success or the last error encountered among these operations. Batching lets you accumulate multiple messages before a flush. Each entry remains a separate message; payloads are not concatenated. The application decides when to flush, for example at the end of an update. Success indicates that the transport accepted the send operations, without confirming processing by the recipient. For Event and Response , the size field must use the combined value described above. For Intention and Notification , it uses the total size directly. Pending batches can be discarded explicitly with clearMessagesBatcher() and are also released at actual network shutdown. A thrown send exception releases the complete queue before propagating to the caller.

